','Add New Notification'=>'Dodaj novo obvestilo','Edit Notification'=>'Uredi obvestilo','Search Notifications'=>'Išči obvestila','No notification found'=>'Obvestilo ni bilo najdeno','PublishPress Planner tried to load multiple times. Please, deactivate and remove other instances of PublishPress, specially if you are using PublishPress Pro.'=>'PublishPress Planner je poskušal naložiti večkrat. Prosimo, deaktivirajte in odstranite druge instance PublishPress, še posebej, če uporabljate PublishPress Pro.','Warning'=>'Opozorilo','%1$s = start date, %2$s = end date %1$s <div class="input-divider">to</div> %2$s'=>' %1$s <div class="input-divider">do</div> %2$s','taxonomy general nameEditorial Field'=>'Urejevalsko polje','taxonomy singular nameEditorial Field'=>'Uredniško polje']];